select 


order by jii.valid_start_date desc, jii.journal_name, jii.issn
limit #{criteria.safeSize} offset #{criteria.offset}

select version_status
from evaluation_rule_versions
where rule_version_id = #{ruleVersionId}

select 

where jii.rule_version_id = #{request.ruleVersionId}
  and jii.issn = #{request.issn}
  and jii.valid_start_date = #{request.validStartDate}
  and jii.valid_end_date = #{request.validEndDate}

select count(*)
from journal_indexing_infos jii
where jii.issn = #{request.issn}
  and jii.active_yn = 'Y'
  and daterange(jii.valid_start_date, jii.valid_end_date, '[]') && daterange(#{request.validStartDate}, #{request.validEndDate}, '[]')
  and not (jii.rule_version_id = #{request.ruleVersionId}
           and jii.valid_start_date = #{request.validStartDate}
           and jii.valid_end_date = #{request.validEndDate})
